#!/usr/bin/env bash
# code-security-reviewer, DG7 round 1 (T-DG7-REV-CS-RG1): reproduction for the S3 secret-assignment exemption.
# Usage: s3-lowercase-secret-repro.sh <candidate-clone-root>
# Builds fixtures under $TMPDIR at run time (no secret-shaped value is committed: each value is generated by openssl,
# the same generator deploy/scripts/init-secrets.sh uses), then runs the candidate's secret scanner on them with --path.
set -u
REPO="$1"
W="$(mktemp -d "${TMPDIR:?}/s3repro.XXXXXX")"
HEX24="$(openssl rand -hex 24)"     # init-secrets.sh rand(): 48 lower-case hex characters
HEX16="$(openssl rand -hex 16)"     # storage.md access_key_id shape: 32 lower-case hex characters
LOWER="$(openssl rand -base64 48 | tr -dc 'a-z0-9' | head -c 24)"  # a lower-case alphanumeric password
MIXED="$(openssl rand -base64 18 | tr -dc 'A-Za-z0-9' | head -c 24)" # control: a mixed-case value of the same length
mkdir -p "$W/a" "$W/b" "$W/c" "$W/d"
printf 'services:\n  db:\n    environment:\n      POSTGRES_PASSWORD: %s\n' "$HEX24" > "$W/a/compose.override.yaml"
printf 'storage:\n  s3_access_key: %s\n' "$HEX16" > "$W/b/values.yaml"
printf 'OIDC_CLIENT_SECRET="%s"\n' "$LOWER" > "$W/c/deploy.conf"
printf 'OIDC_CLIENT_SECRET="%s"\n' "$MIXED" > "$W/d/deploy.conf"
for case in a b c d; do
  echo "--- case $case: $(sed -E 's/(: |=")[^"]*"?$/\1<value>/' "$W/$case"/* | tail -1)"
  node "$REPO/tools/release/secret-scan.mjs" --path "$W/$case"
  echo "exit=$?"
done
echo "--- isNonSecretValue() on the same values (true = exempted):"
node --input-type=module -e "
import { isNonSecretValue, entropy } from '$REPO/tools/release/secret-scan.mjs';
for (const [k, v, label] of [['POSTGRES_PASSWORD', '$HEX24', 'hex24'], ['s3_access_key', '$HEX16', 'hex16'], ['OIDC_CLIENT_SECRET', '$LOWER', 'lower24'], ['OIDC_CLIENT_SECRET', '$MIXED', 'mixed24']])
  console.log(label, 'length', v.length, 'entropy', entropy(v).toFixed(2), 'exempt', isNonSecretValue(k, v));
"
rm -rf "$W"
